#!/usr/bin/env python3
"""Generate the explicit distributed-method registry. --check never writes files."""
import argparse
import json
from pathlib import Path
import re

root = Path(__file__).resolve().parents[1]
parser = argparse.ArgumentParser()
parser.add_argument("--check", action="store_true")
args = parser.parse_args()
manifest = json.loads((root / "Protocol/actor-rpc.json").read_text())
assert manifest["version"] == 1
methods = manifest["methods"]
assert len({m["id"] for m in methods}) == len(methods)
assert len({(m["actor"], m["method"]) for m in methods}) == len(methods)
lines = ["// Generated by Protocol/generate_actor_rpc.py; edit Protocol/actor-rpc.json.",
         "import Foundation", "import IMActorSystem", "import IMV2ActorContracts", "",
         "public enum V2ActorRPCManifest {",
         "    private static let cache = RegistryCache()",
         "    public static func methods() async throws -> [IMMethod] { try await cache.methods() }",
         "    public static func makeSystem(_ name: String, settings input: IMActorSystemSettings) async throws -> IMActorSystem {",
         "        var settings = input",
         "        if settings.methods.isEmpty { settings.methods = try await methods() }",
         "        if !settings.errorTypes.contains(where: { $0.wireTypeID == V2ActorAuthenticationError.wireTypeID }) {",
         "            settings.errorTypes.append(V2ActorAuthenticationError.self)",
         "        }",
         "        return try await IMActorSystem(name, settings: settings)",
         "    }",
         "    private actor RegistryCache {",
         "        private var work: Task<[IMMethod], any Error>?",
         "        func methods() async throws -> [IMMethod] {",
         "            if let work { return try await work.value }",
         "            let task = Task { try await V2ActorRPCManifest.build() }",
         "            work = task; return try await task.value",
         "        }", "    }",
         "    private static func build() async throws -> [IMMethod] {",
         '        let packet = V2ActorSignedPacket(signerID: try .init("registration"), body: Data(), signature: Data())',
         "        let challenge = UUID()", "        var result: [IMMethod] = []"]
for method in sorted(methods, key=lambda m: m["id"]):
    assert 0 < method["id"] < 2**32
    assert method["traffic"] in {"control", "rpc", "bulk"}
    assert method["argument"] in {"packet", "challenge"}
    assert all(re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", method[k]) for k in ("actor", "method"))
    discard = "" if method["void"] else "_ = "
    lines += [f'        result.append(try await IMActorSystem.register(id: {method["id"]}, traffic: .{method["traffic"]}, actor: {method["actor"]}.self) {{',
              f'            {discard}try await $0.{method["method"]}({method["argument"]})', "        })"]
lines += ["        return result", "    }", "}", ""]
output = "\n".join(lines)
destination = root / "Sources/IMV2ActorCluster/Generated/V2ActorRPCManifest.swift"
if args.check:
    if destination.read_text() != output:
        raise SystemExit("RPC registry is stale; run Protocol/generate_actor_rpc.py")
else:
    destination.write_text(output)
